/***************************************************************************************************** 
 *
 * Given an array of non-negative integers, you are initially positioned at the first index of the 
 * array.
 * 
 * Each element in the array represents your maximum jump length at that position.
 * 
 * Determine if you are able to reach the last index.
 * 
 * Example 1:
 * 
 * Input: nums = [2,3,1,1,4]
 * Output: true
 * Explanation: Jump 1 step from index 0 to 1, then 3 steps to the last index.
 * 
 * Example 2:
 * 
 * Input: nums = [3,2,1,0,4]
 * Output: false
 * Explanation: You will always arrive at index 3 no matter what. Its maximum jump length is 0, which 
 * makes it impossible to reach the last index.
 * 
 * Constraints:
 * 
 * 	1 <= nums.length <= 3 * 10^4
 * 	0 <= nums[i][j] <= 10^5
 ******************************************************************************************************/

class Solution {
public:
    bool canJump(vector<int>& nums) {
        int rightmost = 0;
        int n = nums.size();
        for(int i=0;i<n;i++){
            if (i<=rightmost){
                rightmost = max(rightmost,i+nums[i]);
                if (rightmost >= n-1){
                    return true;
                }
            }
        }
        return false;
    }
};

class Solution {
public:
    bool canJump(vector<int>& nums) {
        int n = nums.size() - 1;
        if (n == 0) return true;
        for (int i = nums.size() - 1; i >= 0; i--) {
            if (i + nums[i] >= n) n = i;
        }
        return n == 0;
    }
};

